<?php require_once __DIR__.'/../app/db.php'; require_once __DIR__.'/../app/helpers.php'; require_once __DIR__.'/../app/auth.php'; require_login(); require_perm('contrats'); $pdo=pdo(); $stmt=$pdo->prepare("SELECT r.*, c.*, v.immatriculation, v.marque, v.modele, v.carburant, v.kilometrage_actuel FROM reservations r JOIN clients c ON c.id=r.client_id JOIN voitures v ON v.id=r.voiture_id WHERE r.id=?"); $stmt->execute([getv('id')]); $r=$stmt->fetch(); if(!$r) die('Contrat introuvable'); ?><!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Contrat <?=e($r['reference'])?></title><link rel="stylesheet" href="/assets/style.css"></head><body class="print-body"><div class="contract"><div class="contract-head"><div><h1>CONTRAT DE LOCATION DE VOITURE</h1><p>LAHLAL CAR SARL/AU — Ain Beni Mathar</p></div><b><?=e($r['reference'])?></b></div><section><h2>1. Locataire principal</h2><div class="info-grid"><p><b>Nom complet:</b> <?=e($r['nom'].' '.$r['prenom'])?></p><p><b>Téléphone:</b> <?=e($r['telephone'])?></p><p><b>Nationalité:</b> <?=e($r['nationalite'])?></p><p><b>CIN/Passeport:</b> <?=e($r['cin'] ?: $r['passport'])?></p><p><b>Permis:</b> <?=e($r['numero_permis'])?></p><p><b>Adresse:</b> <?=e($r['adresse'])?></p></div></section><?php if($r['avec_conducteur2']): ?><section><h2>2. Deuxième conducteur autorisé</h2><div class="info-grid"><p><b>Nom complet:</b> <?=e($r['conducteur2_nom'].' '.$r['conducteur2_prenom'])?></p><p><b>Téléphone:</b> <?=e($r['conducteur2_telephone'])?></p><p><b>Nationalité:</b> <?=e($r['conducteur2_nationalite'])?></p><p><b>CIN/Passeport:</b> <?=e($r['conducteur2_cin'] ?: $r['conducteur2_passport'])?></p><p><b>Permis:</b> <?=e($r['conducteur2_permis'])?></p><p><b>Adresse:</b> <?=e($r['conducteur2_adresse'])?></p></div></section><?php endif; ?><section><h2>3. Véhicule</h2><div class="info-grid"><p><b>Véhicule:</b> <?=e($r['marque'].' '.$r['modele'])?></p><p><b>Immatriculation:</b> <?=e($r['immatriculation'])?></p><p><b>Carburant:</b> <?=e($r['carburant'])?></p><p><b>Kilométrage départ:</b> <?=e($r['kilometrage_actuel'])?> km</p></div></section><section><h2>4. Période et paiement</h2><div class="info-grid"><p><b>Début:</b> <?=e($r['date_debut'].' '.$r['heure_depart'])?></p><p><b>Fin:</b> <?=e($r['date_fin'].' '.$r['heure_retour'])?></p><p><b>Lieu départ:</b> <?=e($r['lieu_depart'])?></p><p><b>Lieu retour:</b> <?=e($r['lieu_retour'])?></p><p><b>Prix/jour:</b> <?=money($r['prix_jour'])?></p><p><b>Total:</b> <?=money($r['total'])?></p><p><b>Avance:</b> <?=money($r['avance'])?></p><p><b>Reste:</b> <?=money($r['reste'])?></p></div></section><section><h2>5. Conditions</h2><p><?=nl2br(e($r['conditions']))?></p></section><div class="signatures"><div>Signature client</div><div>Signature agence</div></div><button class="btn primary no-print" onclick="window.print()">Imprimer / PDF</button></div></body></html>
